WITH filtered AS (SELECT *, LAST_DAY(order_date) order_date_month_end, COALESCE(channel, 'OTHER') channel_filled FROM orders WHERE order_date > DATE '2023-09-21' AND customer_id IS NOT NULL), with_windows AS (SELECT *, STDDEV_SAMP(discount) OVER (PARTITION BY status) status_stddev_samp_discount, DENSE_RANK() OVER (PARTITION BY status ORDER BY shipping_fee DESC NULLS LAST) shipping_fee_dense_rank, CORR(shipping_fee, discount) OVER (PARTITION BY store_id) corr_shipping_fee_discount, NTILE(5) OVER (PARTITION BY store_id ORDER BY amount DESC, id) amount_bucket, DENSE_RANK() OVER (ORDER BY shipping_fee DESC) shipping_fee_dense_rank_2 FROM filtered WHERE order_date BETWEEN '2023-07-01' AND '2024-12-01'), metrics AS (SELECT *, LEAD(amount) OVER w_grp next_amount, LEAD(amount_bucket) OVER w_grp next_amount_bucket, LAG(amount_bucket) OVER w_grp prev_amount_bucket, ROW_NUMBER() OVER w_grp row_seq FROM with_windows WINDOW w_grp AS (PARTITION BY store_id ORDER BY shipping_fee_dense_rank, id)), filtered_orders AS (SELECT *, shipping_fee_dense_rank_2 / NULLIF(status_stddev_samp_discount, 0) shipping_fee_dense_rank_2_per_status_stddev_samp_discount FROM metrics WHERE channel IS NOT NULL AND row_seq < 4), attributed AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM filtered_orders e JOIN promotions pr ON e.channel <=> pr.channel AND e.order_date >= pr.starts_on AND e.order_date < pr.ends_on + INTERVAL '30' DAY), with_latest AS (SELECT s.id, s.customer_id, s.status, s.shipping_fee, s.order_date_month_end, s.channel_filled, s.status_stddev_samp_discount, s.shipping_fee_dense_rank_2, s.prev_amount_bucket, s.row_seq, s.shipping_fee_dense_rank_2_per_status_stddev_samp_discount, s.promo_id, s.promo_code, s.discount_pct, top1.shipment_status, top1.shipment_carrier FROM attributed s LEFT JOIN LATERAL (SELECT c.status AS shipment_status, c.carrier AS shipment_carrier FROM shipments c WHERE c.order_id = s.id ORDER BY c.shipped_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT *, NTILE(3) OVER (PARTITION BY customer_id ORDER BY shipping_fee_dense_rank_2 DESC, id, promo_id) shipping_fee_dense_rank_2_bucket, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY shipping_fee_dense_rank_2_per_status_stddev_samp_discount DESC, id, promo_id) row_seq_2, NTILE(5) OVER (PARTITION BY promo_code ORDER BY shipping_fee DESC, id, promo_id) shipping_fee_bucket FROM with_latest
